import { type DescField, ScalarType } from "@bufbuild/protobuf";
import { FeatureSet_FieldPresence } from "@bufbuild/protobuf/wkt";

const GOOGLE_PROTOBUF_PREFIX = "google.protobuf.";

export const TIMESTAMP_TYPE = `${GOOGLE_PROTOBUF_PREFIX}Timestamp`;
export const DURATION_TYPE = `${GOOGLE_PROTOBUF_PREFIX}Duration`;
export const FIELD_MASK_TYPE = `${GOOGLE_PROTOBUF_PREFIX}FieldMask`;
export const STRUCT_TYPE = `${GOOGLE_PROTOBUF_PREFIX}Struct`;
export const VALUE_TYPE = `${GOOGLE_PROTOBUF_PREFIX}Value`;
export const LIST_VALUE_TYPE = `${GOOGLE_PROTOBUF_PREFIX}ListValue`;
export const ANY_TYPE = `${GOOGLE_PROTOBUF_PREFIX}Any`;

export type ScalarField = Extract<DescField, { fieldKind: "scalar" }>;
export type EnumField = Extract<DescField, { fieldKind: "enum" }>;
export type MessageField = Extract<DescField, { fieldKind: "message" }>;
export type ListField = Extract<DescField, { fieldKind: "list" }>;
export type MapField = Extract<DescField, { fieldKind: "map" }>;

export function tracksPresence(field: DescField): boolean {
  return field.presence !== FeatureSet_FieldPresence.IMPLICIT;
}

export function is64BitScalar(scalar: ScalarType | undefined): boolean {
  return (
    scalar === ScalarType.INT64 ||
    scalar === ScalarType.UINT64 ||
    scalar === ScalarType.SINT64 ||
    scalar === ScalarType.FIXED64 ||
    scalar === ScalarType.SFIXED64
  );
}

export function cloneField(field: DescField, overrides: Partial<DescField>): DescField {
  return {
    ...field,
    ...overrides,
  } as DescField;
}

import {
  FieldBehavior,
  field_behavior as fieldBehaviorExtension,
} from "@buf/googleapis_googleapis.bufbuild_es/google/api/field_behavior_pb.js";
import { create, type DescField, type DescMessage, type DescOneof, getExtension } from "@bufbuild/protobuf";
import { type FieldMask, FieldMaskSchema, FieldOptionsSchema } from "@bufbuild/protobuf/wkt";

type FormRecord = Record<string, unknown>;

const NON_UPDATABLE_BEHAVIORS = new Set([FieldBehavior.IDENTIFIER, FieldBehavior.IMMUTABLE, FieldBehavior.OUTPUT_ONLY]);

function isRecord(value: unknown): value is FormRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function valuesEqual(left: unknown, right: unknown): boolean {
  if (Object.is(left, right)) {
    return true;
  }
  if (left instanceof Date && right instanceof Date) {
    return left.getTime() === right.getTime();
  }
  if (left instanceof Uint8Array && right instanceof Uint8Array) {
    return (
      left.length === right.length &&
      left.byteLength === right.byteLength &&
      left.every((value, index) => value === right[index])
    );
  }
  if (Array.isArray(left) && Array.isArray(right)) {
    return left.length === right.length && left.every((value, index) => valuesEqual(value, right[index]));
  }
  if (!(isRecord(left) && isRecord(right))) {
    return false;
  }

  const leftKeys = Object.keys(left);
  const rightKeys = Object.keys(right);
  return (
    leftKeys.length === rightKeys.length &&
    leftKeys.every((key) => Object.hasOwn(right, key) && valuesEqual(left[key], right[key]))
  );
}

/** Build the dirty-field tree expected by createUpdateMask from two value snapshots. */
export function dirtyFieldsFromValues(current: unknown, initial: unknown): FormRecord {
  if (valuesEqual(current, initial)) {
    return {};
  }
  if (!(isRecord(current) && isRecord(initial))) {
    return {};
  }

  const dirtyFields: FormRecord = {};
  const keys = new Set([...Object.keys(current), ...Object.keys(initial)]);
  for (const key of keys) {
    const currentValue = current[key];
    const initialValue = initial[key];
    if (valuesEqual(currentValue, initialValue)) {
      continue;
    }
    dirtyFields[key] =
      isRecord(currentValue) && isRecord(initialValue) ? dirtyFieldsFromValues(currentValue, initialValue) : true;
  }
  return dirtyFields;
}

function hasDirtyValue(value: unknown): boolean {
  if (value === true) {
    return true;
  }
  if (Array.isArray(value)) {
    return value.some(hasDirtyValue);
  }
  if (isRecord(value)) {
    return Object.values(value).some(hasDirtyValue);
  }
  return false;
}

function fieldPath(prefix: string, field: DescField): string {
  return prefix ? `${prefix}.${field.name}` : field.name;
}

function isUpdatableField(field: DescField): boolean {
  const behaviors = getExtension(field.proto.options ?? create(FieldOptionsSchema), fieldBehaviorExtension);
  return behaviors.every((behavior) => !NON_UPDATABLE_BEHAVIORS.has(behavior));
}

function findField(schema: DescMessage, segment: string): DescField | undefined {
  return schema.fields.find(
    (field) => field.localName === segment || field.name === segment || field.jsonName === segment
  );
}

function normalizeFieldPath(schema: DescMessage, path: string): string {
  if (path === "*") {
    return path;
  }

  const segments = path.split(".").filter(Boolean);
  if (segments.length === 0) {
    throw new Error("Field mask paths cannot be empty.");
  }

  const normalized: string[] = [];
  let currentSchema = schema;
  for (const [index, segment] of segments.entries()) {
    const field = findField(currentSchema, segment);
    if (!field) {
      throw new Error(`Unknown field mask path: ${path}`);
    }
    normalized.push(field.name);

    if (index === segments.length - 1) {
      break;
    }
    if (field.fieldKind === "list" || field.fieldKind === "map") {
      break;
    }
    if (field.fieldKind !== "message") {
      throw new Error(`Field mask path cannot traverse scalar field: ${path}`);
    }
    currentSchema = field.message;
  }
  return normalized.join(".");
}

function fieldOrder(schema: DescMessage, path: string): number[] {
  if (path === "*") {
    return [-1];
  }

  const order: number[] = [];
  let currentSchema = schema;
  for (const segment of path.split(".")) {
    const index = currentSchema.fields.findIndex((candidate) => candidate.name === segment);
    order.push(index);
    const field = currentSchema.fields[index];
    if (field?.fieldKind !== "message") {
      break;
    }
    currentSchema = field.message;
  }
  return order;
}

function compareFieldOrder(schema: DescMessage, left: string, right: string): number {
  const leftOrder = fieldOrder(schema, left);
  const rightOrder = fieldOrder(schema, right);
  const length = Math.max(leftOrder.length, rightOrder.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (leftOrder[index] ?? -1) - (rightOrder[index] ?? -1);
    if (difference !== 0) {
      return difference;
    }
  }
  return left.localeCompare(right);
}

/** Build a validated, canonical FieldMask from TypeScript or protobuf paths. */
export function createFieldMask(schema: DescMessage, paths: readonly string[]): FieldMask {
  const normalizedPaths = [...new Set(paths.map((path) => normalizeFieldPath(schema, path)))];
  if (normalizedPaths.includes("*")) {
    return create(FieldMaskSchema, { paths: ["*"] });
  }
  const minimizedPaths = normalizedPaths.filter(
    (path) => !normalizedPaths.some((candidate) => candidate !== path && path.startsWith(`${candidate}.`))
  );
  minimizedPaths.sort((left, right) => compareFieldOrder(schema, left, right));
  return create(FieldMaskSchema, { paths: minimizedPaths });
}

function collectFieldPaths(
  field: DescField,
  dirtyValue: unknown,
  currentValue: unknown,
  initialValue: unknown,
  prefix: string
): string[] {
  if (!(hasDirtyValue(dirtyValue) && isUpdatableField(field))) {
    return [];
  }

  const path = fieldPath(prefix, field);
  if (dirtyValue === true || field.fieldKind === "list" || field.fieldKind === "map") {
    return [path];
  }
  if (field.fieldKind !== "message" || !isRecord(dirtyValue)) {
    return [path];
  }

  const nestedPaths = collectMessagePaths(
    field.message,
    dirtyValue,
    isRecord(currentValue) ? currentValue : {},
    isRecord(initialValue) ? initialValue : {},
    path
  );
  return nestedPaths.length > 0 ? nestedPaths : [path];
}

function collectOneofPaths(
  oneof: DescOneof,
  dirtyValue: unknown,
  currentValue: unknown,
  initialValue: unknown,
  prefix: string
): string[] {
  if (!hasDirtyValue(dirtyValue)) {
    return [];
  }

  const selectedOneof =
    isRecord(currentValue) && typeof currentValue["case"] === "string" ? currentValue : initialValue;
  if (!isRecord(selectedOneof)) {
    return [];
  }
  const selectedCase = selectedOneof["case"];
  if (typeof selectedCase !== "string") {
    return [];
  }
  const selectedField = oneof.fields.find((field) => field.localName === selectedCase);
  if (!selectedField) {
    return [];
  }

  const nestedDirtyValue =
    isRecord(dirtyValue) && dirtyValue["case"] !== true && hasDirtyValue(dirtyValue["value"])
      ? dirtyValue["value"]
      : true;
  const initialOneofValue = isRecord(initialValue) ? initialValue["value"] : undefined;
  return collectFieldPaths(selectedField, nestedDirtyValue, selectedOneof["value"], initialOneofValue, prefix);
}

function collectMessagePaths(
  schema: DescMessage,
  dirtyFields: FormRecord,
  currentValues: FormRecord,
  initialValues: FormRecord,
  prefix = ""
): string[] {
  return schema.members.flatMap((member) => {
    if (member.kind === "oneof") {
      return collectOneofPaths(
        member,
        dirtyFields[member.localName],
        currentValues[member.localName],
        initialValues[member.localName],
        prefix
      );
    }
    return collectFieldPaths(
      member,
      dirtyFields[member.localName],
      currentValues[member.localName],
      initialValues[member.localName],
      prefix
    );
  });
}

/** Build an update mask from react-hook-form's dirty field tree. */
export function createUpdateMask(
  schema: DescMessage,
  dirtyFields: unknown,
  currentValues: unknown,
  initialValues?: unknown
): FieldMask {
  const paths = collectMessagePaths(
    schema,
    isRecord(dirtyFields) ? dirtyFields : {},
    isRecord(currentValues) ? currentValues : {},
    isRecord(initialValues) ? initialValues : {}
  );
  return createFieldMask(schema, paths);
}

import type { DescMessage, MessageValidType } from "@bufbuild/protobuf";
import type { FormValues, StandardSchemaV1 } from "../core/index.js";

import { type ProtoFormOptions, validateFormValuesAgainstProtoSchema } from "./hook-runtime.js";
import { createDescriptorAwareStandardSchema } from "./validation-schema.js";

function isFormValueObject(value: unknown): value is FormValues {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Expose protovalidate + CEL validation of a proto message as a Standard
 * Schema over FORM values: input is the form value bag, output is the
 * validated typed message, and failure issues carry form-shaped paths
 * (camelCase keys, oneofs flattened, map keys resolved to entry indices).
 *
 * This is the interop seam: anything that speaks Standard Schema v1
 * (React Hook Form via standardSchemaResolver, TanStack Form natively)
 * gets proto validation without importing protovalidate directly.
 */
export function createProtoFormSchema<Input extends object = FormValues, Desc extends DescMessage = DescMessage>(
  desc: Desc,
  options: ProtoFormOptions = {}
): StandardSchemaV1<Input, MessageValidType<Desc>> {
  const messageSchema = createDescriptorAwareStandardSchema(desc, options);

  return {
    "~standard": {
      validate: (value) => {
        if (!isFormValueObject(value)) {
          return {
            issues: [{ message: "Expected form values to be an object.", path: [] }],
          };
        }
        return validateFormValuesAgainstProtoSchema(desc, value, messageSchema, options);
      },
      vendor: "protoform",
      version: 1,
    },
  };
}

import {
  BadRequestSchema,
  DebugInfoSchema,
  ErrorInfoSchema,
  HelpSchema,
  LocalizedMessageSchema,
  PreconditionFailureSchema,
  QuotaFailureSchema,
  RequestInfoSchema,
  ResourceInfoSchema,
  RetryInfoSchema,
} from "@buf/googleapis_googleapis.bufbuild_es/google/rpc/error_details_pb.js";
import { Code, ConnectError } from "@connectrpc/connect";

const CODE_LABELS: Record<number, string> = {
  [Code.Canceled]: "canceled",
  [Code.Unknown]: "unknown",
  [Code.InvalidArgument]: "invalid_argument",
  [Code.DeadlineExceeded]: "deadline_exceeded",
  [Code.NotFound]: "not_found",
  [Code.AlreadyExists]: "already_exists",
  [Code.PermissionDenied]: "permission_denied",
  [Code.ResourceExhausted]: "resource_exhausted",
  [Code.FailedPrecondition]: "failed_precondition",
  [Code.Aborted]: "aborted",
  [Code.OutOfRange]: "out_of_range",
  [Code.Unimplemented]: "unimplemented",
  [Code.Internal]: "internal",
  [Code.Unavailable]: "unavailable",
  [Code.DataLoss]: "data_loss",
  [Code.Unauthenticated]: "unauthenticated",
};

/**
 * Get a human-readable label for a gRPC status code.
 */
export function grpcCodeLabel(code: number): string {
  return CODE_LABELS[code] ?? `code_${code}`;
}

/**
 * Extract a human-readable message from a Connect/gRPC error.
 * Preserves all available information: message, field violations, and gRPC code.
 */
export function formatConnectError(error: unknown): string {
  if (error instanceof ConnectError) {
    const violations = extractFieldViolations(error);
    const { code, rawMessage } = error;
    const codeLabel = grpcCodeLabel(code);

    const parts: string[] = [];
    if (rawMessage) {
      parts.push(rawMessage);
    }
    if (violations.length > 0) {
      parts.push(violations.map((v) => `${v.field}: ${v.description}`).join("; "));
    }
    if (parts.length === 0) {
      return codeLabel;
    }
    return `${parts.join(" — ")} (code: ${codeLabel})`;
  }
  if (error instanceof Error) {
    return error.message;
  }
  return String(error);
}

export interface FieldViolation {
  description: string;
  field: string;
}

/**
 * Extract field violations from Connect error details via the generated
 * `google.rpc.BadRequest` schema. Returns an empty array when no
 * BadRequest detail is attached or parsing fails.
 */
export function extractFieldViolations(error: ConnectError): FieldViolation[] {
  const violations: FieldViolation[] = [];
  try {
    for (const badRequest of error.findDetails(BadRequestSchema)) {
      for (const v of badRequest.fieldViolations) {
        violations.push({ description: v.description, field: v.field });
      }
    }
  } catch {
    // Unexpected parse failure: fall through to empty.
  }
  return violations;
}

/**
 * Format a toast error message for API operations.
 * Pattern: "Failed to {action} {entity}: {formatted error with code}"
 */
export function formatToastErrorMessage({
  action,
  entity,
  error,
}: {
  action: string;
  entity: string;
  error: unknown;
}): string {
  return `Failed to ${action} ${entity}: ${formatConnectError(error)}`;
}

export interface HelpLink {
  description: string;
  url: string;
}

export interface PreconditionViolation {
  description: string;
  subject: string;
  type: string;
}

export interface QuotaViolation {
  description: string;
  subject: string;
}

export interface ConnectErrorContext {
  /** gRPC status code label (e.g. "invalid_argument"). Always populated for ConnectError. */
  code?: string;
  /** Dev-only stack frames / detail from google.rpc.DebugInfo. */
  debug?: { detail?: string; stackEntries?: string[] };
  /** Service domain from `google.rpc.ErrorInfo`. */
  domain?: string;
  /** Links the backend suggests the user follow (docs, status pages). */
  helpLinks: HelpLink[];
  /** Human-friendly top-level message. Prefers `LocalizedMessage.message` over `rawMessage`. */
  message?: string;
  /** Locale of the localized message if one was provided. */
  messageLocale?: string;
  /** Extra ErrorInfo metadata the server attached. */
  metadata?: Record<string, string>;
  /** Precondition failures (typed, not per-field). */
  preconditionViolations: PreconditionViolation[];
  /** Quota failures. */
  quotaViolations: QuotaViolation[];
  /** Domain-scoped machine reason from `google.rpc.ErrorInfo` (useful for logs/telemetry). */
  reason?: string;
  /** Opaque request identifier for support tickets. */
  requestId?: string;
  /** Affected resource, if reported. */
  resource?: {
    name?: string | undefined;
    type?: string | undefined;
    description?: string | undefined;
  };
  /** Retry hint in seconds. Set on rate-limit / resource-exhausted responses. */
  retryAfterSeconds?: number;
  /** Detail type names not interpreted by Protoform, preserved for fallback UI and telemetry. */
  unmappedDetails: string[];
}

const MAPPED_DETAIL_TYPES: ReadonlySet<string> = new Set([
  BadRequestSchema.typeName,
  DebugInfoSchema.typeName,
  ErrorInfoSchema.typeName,
  HelpSchema.typeName,
  LocalizedMessageSchema.typeName,
  PreconditionFailureSchema.typeName,
  QuotaFailureSchema.typeName,
  RequestInfoSchema.typeName,
  ResourceInfoSchema.typeName,
  RetryInfoSchema.typeName,
]);

function connectDetailTypeName(detail: ConnectError["details"][number]): string | undefined {
  if ("desc" in detail) {
    return detail.desc.typeName;
  }
  return detail.type || undefined;
}

/**
 * Extract every surfacable detail from a `ConnectError` into one context object.
 * Non-ConnectError inputs yield an empty context (safe to render). All fields
 * optional; callers render only the pieces that are present.
 *
 * Uses `ConnectError.findDetails(Schema)` with the generated google.rpc.*
 * schemas so we don't hand-walk wire-format JSON. Types come from the proto
 * source of truth and handle both `value` (binary) and `debug` (JSON)
 * representations the Connect runtime surfaces.
 */
export function extractConnectErrorContext(error: unknown): ConnectErrorContext {
  const context: ConnectErrorContext = {
    helpLinks: [],
    preconditionViolations: [],
    quotaViolations: [],
    unmappedDetails: [],
  };

  if (!(error instanceof ConnectError)) {
    return context;
  }

  context.code = grpcCodeLabel(error.code);
  if (error.rawMessage) {
    context.message = error.rawMessage;
  }
  context.unmappedDetails = [
    ...new Set(
      error.details.flatMap((detail) => {
        const typeName = connectDetailTypeName(detail);
        return typeName && !MAPPED_DETAIL_TYPES.has(typeName) ? [typeName] : [];
      })
    ),
  ];

  try {
    // LocalizedMessage overrides rawMessage when present, carries locale.
    for (const localized of error.findDetails(LocalizedMessageSchema)) {
      if (localized.message) {
        context.message = localized.message;
        if (localized.locale) {
          context.messageLocale = localized.locale;
        }
      }
    }

    // Help: docs / status links the backend suggests.
    for (const help of error.findDetails(HelpSchema)) {
      for (const link of help.links) {
        if (link.url) {
          context.helpLinks.push({
            description: link.description || link.url,
            url: link.url,
          });
        }
      }
    }

    // ErrorInfo: machine reason/domain for telemetry, plus metadata (request_id stash).
    for (const info of error.findDetails(ErrorInfoSchema)) {
      if (info.reason) {
        context.reason = info.reason;
      }
      if (info.domain) {
        context.domain = info.domain;
      }
      const metaKeys = Object.keys(info.metadata);
      if (metaKeys.length > 0) {
        context.metadata = { ...info.metadata };
        const metaReq = info.metadata["request_id"] ?? info.metadata["requestId"];
        if (metaReq && !context.requestId) {
          context.requestId = metaReq;
        }
      }
    }

    // RequestInfo: explicit request id (takes precedence over ErrorInfo.metadata).
    for (const req of error.findDetails(RequestInfoSchema)) {
      if (req.requestId) {
        context.requestId = req.requestId;
      }
    }

    // RetryInfo: seconds-until-retry hint. google.protobuf.Duration has
    // `seconds: bigint` + `nanos: number` in proto v2 generated types.
    for (const retry of error.findDetails(RetryInfoSchema)) {
      if (retry.retryDelay) {
        const { nanos, seconds: retrySeconds } = retry.retryDelay;
        const seconds = Number(retrySeconds);
        context.retryAfterSeconds = seconds + nanos / 1e9;
      }
    }

    // DebugInfo: dev-only stack trace / detail.
    for (const dbg of error.findDetails(DebugInfoSchema)) {
      context.debug = { detail: dbg.detail, stackEntries: dbg.stackEntries };
    }

    // PreconditionFailure: typed violations (TOS, plan, etc.).
    for (const pre of error.findDetails(PreconditionFailureSchema)) {
      for (const v of pre.violations) {
        context.preconditionViolations.push({
          description: v.description,
          subject: v.subject,
          type: v.type,
        });
      }
    }

    // QuotaFailure: quota exhaustion details.
    for (const quota of error.findDetails(QuotaFailureSchema)) {
      for (const v of quota.violations) {
        context.quotaViolations.push({
          description: v.description,
          subject: v.subject,
        });
      }
    }

    // ResourceInfo: affected resource descriptor.
    for (const resource of error.findDetails(ResourceInfoSchema)) {
      context.resource = {
        description: resource.description || undefined,
        name: resource.resourceName || undefined,
        type: resource.resourceType || undefined,
      };
    }
  } catch {
    // Malformed details: fall through with whatever we extracted so far.
  }

  return context;
}

import {
  clone,
  create,
  type DescField,
  type DescMessage,
  fromJson,
  fromJsonString,
  isMessage,
  type JsonValue,
  type MessageInitShape,
  type MessageShape,
  type MessageValidType,
  ScalarType,
  toJson,
  toJsonString,
} from "@bufbuild/protobuf";
import { base64Decode, base64Encode } from "@bufbuild/protobuf/wire";
import {
  DurationSchema,
  type FieldMask,
  isWrapperDesc,
  ListValueSchema,
  StructSchema,
  type TimestampSchema,
  timestampDate,
  timestampFromDate,
  ValueSchema,
} from "@bufbuild/protobuf/wkt";
import type { ValidatorOptions } from "@bufbuild/protovalidate";
import type { EmptyRepeatedStringPolicy, FormValues, StandardSchemaV1 } from "../core/index.js";
import type { ProtoformMessageFormatter } from "../core/messages.js";
import {
  ANY_TYPE,
  cloneField,
  DURATION_TYPE,
  FIELD_MASK_TYPE,
  is64BitScalar,
  LIST_VALUE_TYPE,
  type ListField,
  type MapField,
  type MessageField,
  type ScalarField,
  STRUCT_TYPE,
  TIMESTAMP_TYPE,
  tracksPresence,
  VALUE_TYPE,
} from "./descriptor-utils.js";
import { protoPathToFormPath } from "./proto-error-path.js";

const PROTO_JSON_FALLBACK_TYPES = [
  TIMESTAMP_TYPE,
  DURATION_TYPE,
  FIELD_MASK_TYPE,
  STRUCT_TYPE,
  VALUE_TYPE,
  LIST_VALUE_TYPE,
  ANY_TYPE,
];

export const PROTO_FORM_ROOT_ERROR_KEY = "__protoFormRoot__";

type SchemaIssue = StandardSchemaV1.Issue;
type AnyObject = Record<string, unknown>;

export interface ProtoAnyFormValue {
  typeUrl?: string;
  valueBase64?: string;
}

export interface ProtoMapFormEntry {
  key: unknown;
  value: unknown;
}

export interface ProtoConversionOptions {
  /**
   * Per-field policies keyed by descriptor path. Empty and whitespace-only
   * repeated strings are discarded unless the field is set to `preserve`.
   */
  emptyRepeatedStringPolicies?: Readonly<Record<string, EmptyRepeatedStringPolicy>> | undefined;
}

export interface ProtoFormOptions extends ValidatorOptions, ProtoConversionOptions {
  formatMessage?: ProtoformMessageFormatter | undefined;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function toDateTimeLocalValue(timestamp: MessageShape<typeof TimestampSchema> | undefined): string | undefined {
  if (!timestamp) {
    return;
  }

  const date = timestampDate(timestamp);
  if (Number.isNaN(date.getTime())) {
    return;
  }

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  const hours = String(date.getHours()).padStart(2, "0");
  const minutes = String(date.getMinutes()).padStart(2, "0");

  return `${year}-${month}-${day}T${hours}:${minutes}`;
}

function objectHasValues(value: Record<string, unknown>): boolean {
  return Object.values(value).some((entry) => {
    if (entry === undefined || entry === null) {
      return false;
    }
    if (typeof entry === "string") {
      return entry.trim().length > 0;
    }
    if (Array.isArray(entry)) {
      return entry.length > 0;
    }
    if (typeof entry === "object") {
      return isPlainObject(entry) ? objectHasValues(entry) : true;
    }
    return true;
  });
}

function isJsonValue(value: unknown): value is JsonValue {
  if (value === null || typeof value === "string" || typeof value === "boolean") {
    return true;
  }
  if (typeof value === "number") {
    return Number.isFinite(value);
  }
  if (Array.isArray(value)) {
    return value.every(isJsonValue);
  }
  return isPlainObject(value) && Object.values(value).every(isJsonValue);
}

function fieldToFormValue(field: DescField, value: unknown): unknown {
  switch (field.fieldKind) {
    case "scalar": {
      if (field.scalar === ScalarType.BYTES) {
        return value instanceof Uint8Array ? base64Encode(value) : undefined;
      }
      if (is64BitScalar(field.scalar)) {
        return typeof value === "bigint" ? value.toString() : (value ?? undefined);
      }
      return value;
    }
    case "enum":
      return value;
    case "message": {
      if (isWrapperDesc(field.message)) {
        const wrappedScalar = field.message.fields[0]?.scalar;
        if (wrappedScalar === ScalarType.BYTES) {
          return value instanceof Uint8Array ? base64Encode(value) : undefined;
        }
        if (is64BitScalar(wrappedScalar)) {
          return typeof value === "bigint" ? value.toString() : (value ?? undefined);
        }
        return value;
      }

      switch (field.message.typeName) {
        case TIMESTAMP_TYPE:
          return toDateTimeLocalValue(value as MessageShape<typeof TimestampSchema> | undefined);
        case DURATION_TYPE:
          return value
            ? toJsonString(DurationSchema, value as MessageShape<typeof DurationSchema>).replace(/"/gu, "")
            : undefined;
        case FIELD_MASK_TYPE:
          return isPlainObject(value) && Array.isArray((value as { paths?: unknown[] }).paths)
            ? (value as { paths: string[] }).paths
            : undefined;
        case STRUCT_TYPE:
          if (isMessage(value, StructSchema)) {
            return toJson(StructSchema, value);
          }
          return isPlainObject(value) && isJsonValue(value) ? structuredClone(value) : undefined;
        case VALUE_TYPE:
          if (isMessage(value, ValueSchema)) {
            return toJson(ValueSchema, value);
          }
          return isJsonValue(value) ? structuredClone(value) : undefined;
        case LIST_VALUE_TYPE:
          if (isMessage(value, ListValueSchema)) {
            return toJson(ListValueSchema, value);
          }
          return Array.isArray(value) && isJsonValue(value) ? structuredClone(value) : undefined;
        case ANY_TYPE:
          return value && isPlainObject(value)
            ? {
                typeUrl:
                  typeof (value as { typeUrl?: unknown }).typeUrl === "string"
                    ? (value as { typeUrl: string }).typeUrl
                    : "",
                valueBase64:
                  (value as { value?: unknown }).value instanceof Uint8Array
                    ? base64Encode((value as { value: Uint8Array }).value)
                    : "",
              }
            : undefined;
        default:
          return value ? messageToFormValues(field.message, value as AnyObject) : undefined;
      }
    }
    case "list":
      return Array.isArray(value) ? value.map((item) => listItemToFormValue(field, item)) : [];
    case "map": {
      if (!isPlainObject(value)) {
        return [];
      }
      return Object.entries(value).map(
        ([key, entryValue]) =>
          ({
            key: mapKeyToFormValue(field, key),
            value: mapValueToFormValue(field, entryValue),
          }) satisfies ProtoMapFormEntry
      );
    }
    default:
      return value;
  }
}

function listItemToFormValue(field: ListField, value: unknown): unknown {
  if (field.listKind === "message" && value) {
    if (isWrapperDesc(field.message)) {
      return value;
    }
    return messageToFormValues(field.message, value as AnyObject);
  }

  if (field.listKind === "scalar" && field.scalar === ScalarType.BYTES) {
    return value instanceof Uint8Array ? base64Encode(value) : undefined;
  }

  if (field.listKind === "scalar" && is64BitScalar(field.scalar)) {
    return typeof value === "bigint" ? value.toString() : value;
  }

  return value;
}

function mapValueToFormValue(field: MapField, value: unknown): unknown {
  if (field.mapKind === "message" && value) {
    if (isWrapperDesc(field.message)) {
      return value;
    }
    return messageToFormValues(field.message, value as AnyObject);
  }

  if (field.mapKind === "scalar" && field.scalar === ScalarType.BYTES) {
    return value instanceof Uint8Array ? base64Encode(value) : undefined;
  }

  if (field.mapKind === "scalar" && is64BitScalar(field.scalar)) {
    return typeof value === "bigint" ? value.toString() : value;
  }

  return value;
}

function mapKeyToFormValue(field: MapField, key: string): string | number | boolean {
  if (field.mapKey === ScalarType.BOOL) {
    return key === "true";
  }
  if (is64BitScalar(field.mapKey) || field.mapKey === ScalarType.STRING) {
    return key;
  }
  return Number(key);
}

function messageToFormValues(desc: DescMessage, value: AnyObject): Record<string, unknown> {
  const result: Record<string, unknown> = {};

  for (const member of desc.members) {
    if (member.kind === "oneof") {
      const oneofValue = value[member.localName] as { case?: string; value?: unknown } | undefined;
      if (!oneofValue?.case) {
        result[member.localName] = { case: undefined, value: undefined };
        continue;
      }

      const activeField = member.fields.find((field) => field.localName === oneofValue.case);
      result[member.localName] = {
        case: oneofValue.case,
        value: activeField ? fieldToFormValue(activeField, oneofValue.value) : oneofValue.value,
      };
      continue;
    }

    result[member.localName] = fieldToFormValue(member, value[member.localName]);
  }

  return result;
}

export function protoToFormValues<Desc extends DescMessage>(
  desc: Desc,
  value?: MessageShape<Desc>
): Record<string, unknown> {
  const baseValue = (value ?? create(desc)) as AnyObject;
  return messageToFormValues(desc, baseValue);
}

function normalizeBooleanValue(value: unknown): boolean | undefined {
  if (value === undefined || value === null || value === "") {
    return;
  }
  if (typeof value === "boolean") {
    return value;
  }
  if (value === "true") {
    return true;
  }
  if (value === "false") {
    return false;
  }
  return Boolean(value);
}

function normalizeNumberValue(value: unknown): number | undefined {
  if (value === undefined || value === null || value === "") {
    return;
  }
  if (typeof value === "number") {
    return Number.isNaN(value) ? undefined : value;
  }
  const parsed = Number(value);
  return Number.isNaN(parsed) ? undefined : parsed;
}

function normalizeFloatingPointValue(value: unknown): number | undefined {
  if (value === undefined || value === null || value === "") {
    return;
  }
  if (typeof value === "number") {
    return value;
  }
  if (value === "NaN") {
    return Number.NaN;
  }
  const parsed = Number(value);
  return Number.isNaN(parsed) ? undefined : parsed;
}

function normalizeBigIntValue(value: unknown): bigint | undefined {
  if (value === undefined || value === null || value === "") {
    return;
  }
  if (typeof value === "bigint") {
    return value;
  }
  if (typeof value === "number" && Number.isSafeInteger(value)) {
    return BigInt(value);
  }
  if (typeof value === "string") {
    try {
      return BigInt(value);
    } catch {
      return;
    }
  }
  return;
}

function normalizeScalarValue(field: DescField, value: unknown): unknown {
  if (field.scalar === ScalarType.STRING) {
    if (typeof value === "string") {
      return value;
    }

    if (value === undefined || value === null) {
      return;
    }

    return String(value);
  }
  if (field.scalar === ScalarType.BOOL) {
    return normalizeBooleanValue(value);
  }
  if (field.scalar === ScalarType.BYTES) {
    if (typeof value === "string") {
      return base64Decode(value);
    }

    return value instanceof Uint8Array ? value : undefined;
  }
  if (field.scalar === ScalarType.FLOAT || field.scalar === ScalarType.DOUBLE) {
    return normalizeFloatingPointValue(value);
  }
  if (is64BitScalar(field.scalar)) {
    return normalizeBigIntValue(value);
  }
  return normalizeNumberValue(value);
}

function normalizeMessageFieldValue(
  field: MessageField,
  value: unknown,
  options: ProtoConversionOptions,
  path: readonly string[]
): unknown {
  if (isWrapperDesc(field.message)) {
    const wrappedScalar = field.message.fields[0]?.scalar;
    const wrappedField = cloneField(field, {
      fieldKind: "scalar",
      scalar: wrappedScalar,
    });
    return normalizeScalarValue(wrappedField, value);
  }

  switch (field.message.typeName) {
    case TIMESTAMP_TYPE:
      return typeof value === "string" && value ? timestampFromDate(new Date(value)) : undefined;
    case DURATION_TYPE:
      return typeof value === "string" && value ? fromJsonString(DurationSchema, JSON.stringify(value)) : undefined;
    case FIELD_MASK_TYPE:
      return Array.isArray(value) && value.length > 0
        ? {
            paths: value.filter((entry): entry is string => typeof entry === "string"),
          }
        : undefined;
    case STRUCT_TYPE:
      return value === undefined ? undefined : fromJson(StructSchema, (value ?? {}) as JsonValue);
    case VALUE_TYPE:
      return value === undefined ? undefined : fromJson(ValueSchema, value as JsonValue);
    case LIST_VALUE_TYPE:
      return value === undefined ? undefined : fromJson(ListValueSchema, value as JsonValue);
    case ANY_TYPE: {
      const anyValue = isPlainObject(value) ? (value as ProtoAnyFormValue) : undefined;
      if (!(anyValue?.typeUrl || anyValue?.valueBase64)) {
        return;
      }
      return {
        typeUrl: anyValue?.typeUrl ?? "",
        value: base64Decode(anyValue?.valueBase64 ?? ""),
      };
    }
    default: {
      const nested = isPlainObject(value) ? messageToProtoInit(field.message, value, options, path) : undefined;
      if (!(nested && objectHasValues(nested))) {
        return tracksPresence(field) ? undefined : nested;
      }
      return nested;
    }
  }
}

function listItemToProtoValue(
  field: ListField,
  value: unknown,
  options: ProtoConversionOptions,
  path: readonly string[]
): unknown {
  if (field.listKind === "scalar") {
    return normalizeScalarValue(
      cloneField(field, {
        fieldKind: "scalar",
        oneof: undefined,
      }),
      value
    );
  }
  if (field.listKind === "enum") {
    return value === undefined || value === "" ? undefined : Number(value);
  }
  if (isWrapperDesc(field.message)) {
    return value;
  }
  return isPlainObject(value) ? messageToProtoInit(field.message, value, options, path) : undefined;
}

function mapValueToProtoValue(
  field: MapField,
  value: unknown,
  options: ProtoConversionOptions,
  path: readonly string[]
): unknown {
  if (field.mapKind === "scalar") {
    return normalizeScalarValue(
      cloneField(field, {
        fieldKind: "scalar",
        oneof: undefined,
      }),
      value
    );
  }
  if (field.mapKind === "enum") {
    return value === undefined || value === "" ? undefined : Number(value);
  }
  if (isWrapperDesc(field.message)) {
    return value;
  }
  return isPlainObject(value) ? messageToProtoInit(field.message, value, options, path) : undefined;
}

function repeatedListEntries(
  field: ListField,
  value: unknown,
  options: ProtoConversionOptions,
  path: readonly string[]
): unknown[] {
  if (!Array.isArray(value)) {
    return [];
  }
  const policy = options.emptyRepeatedStringPolicies?.[path.join(".")];
  if (field.listKind !== "scalar" || field.scalar !== ScalarType.STRING || policy === "preserve") {
    return value;
  }
  return value.filter((entry) => typeof entry !== "string" || entry.trim().length > 0);
}

function fieldToProtoValue(
  field: DescField,
  value: unknown,
  options: ProtoConversionOptions,
  path: readonly string[]
): unknown {
  switch (field.fieldKind) {
    case "scalar":
      return normalizeScalarValue(field, value);
    case "enum":
      return value === undefined || value === "" ? undefined : Number(value);
    case "message":
      return normalizeMessageFieldValue(field, value, options, path);
    case "list":
      return repeatedListEntries(field, value, options, path).map((entry) =>
        listItemToProtoValue(field, entry, options, path)
      );
    case "map": {
      const entries = isPlainObject(value)
        ? Object.entries(value).map(([key, mapValue]) => ({ key, value: mapValue }))
        : value;
      return Array.isArray(entries)
        ? Object.fromEntries(
            entries
              .map((entry) => {
                if (!isPlainObject(entry)) {
                  return null;
                }
                const mapKey = entry["key"];
                if (mapKey === undefined || mapKey === null || mapKey === "") {
                  return null;
                }
                return [String(mapKey), mapValueToProtoValue(field, entry["value"], options, path)] as const;
              })
              .filter((entry): entry is readonly [string, unknown] => entry !== null)
          )
        : {};
    }
    default:
      return value;
  }
}

function messageToProtoInit(
  desc: DescMessage,
  value: AnyObject,
  options: ProtoConversionOptions,
  path: readonly string[]
): Record<string, unknown> {
  const result: Record<string, unknown> = {};

  for (const member of desc.members) {
    if (member.kind === "oneof") {
      const oneofValue = value[member.localName] as { case?: string; value?: unknown } | undefined;
      if (!oneofValue?.case) {
        continue;
      }

      const activeField = member.fields.find((field) => field.localName === oneofValue.case);
      if (!activeField) {
        continue;
      }

      result[member.localName] = {
        case: oneofValue.case,
        value: fieldToProtoValue(activeField, oneofValue.value, options, [
          ...path,
          member.localName,
          activeField.localName,
        ]),
      };
      continue;
    }

    const normalized = fieldToProtoValue(member, value[member.localName], options, [...path, member.localName]);
    if (normalized === undefined && tracksPresence(member)) {
      continue;
    }
    result[member.localName] = normalized;
  }

  return result;
}

export function formValuesToProtoInit<Desc extends DescMessage>(
  desc: Desc,
  values: Record<string, unknown>,
  options: ProtoConversionOptions = {}
): MessageInitShape<Desc> {
  return messageToProtoInit(desc, values, options, []) as MessageInitShape<Desc>;
}

function knownMessageValuesEqual(desc: DescMessage, left: AnyObject, right: AnyObject): boolean {
  return toJsonString(desc, left as never) === toJsonString(desc, right as never);
}

function preserveRepeatedMessageUnknownFields(desc: DescMessage, target: unknown[], source: unknown[]): void {
  const matchedSourceIndexes = new Set<number>();
  const matchedTargetIndexes = new Set<number>();

  for (const [targetIndex, targetValue] of target.entries()) {
    if (!isPlainObject(targetValue)) {
      continue;
    }
    const candidates = source.flatMap((candidateSourceValue, candidateSourceIndex) =>
      !matchedSourceIndexes.has(candidateSourceIndex) &&
      isPlainObject(candidateSourceValue) &&
      knownMessageValuesEqual(desc, targetValue, candidateSourceValue)
        ? [candidateSourceIndex]
        : []
    );
    if (candidates.length !== 1) {
      continue;
    }
    const [sourceIndex] = candidates;
    if (sourceIndex === undefined) {
      continue;
    }
    const sourceValue = source[sourceIndex];
    if (!isPlainObject(sourceValue)) {
      continue;
    }
    const competingTargetCount = target.filter(
      (candidate, candidateIndex) =>
        !matchedTargetIndexes.has(candidateIndex) &&
        isPlainObject(candidate) &&
        knownMessageValuesEqual(desc, candidate, sourceValue)
    ).length;
    if (competingTargetCount !== 1) {
      continue;
    }
    preserveMessageUnknownFields(desc, targetValue, sourceValue);
    matchedSourceIndexes.add(sourceIndex);
    matchedTargetIndexes.add(targetIndex);
  }

  if (target.length !== source.length) {
    return;
  }

  for (const [index, targetValue] of target.entries()) {
    const sourceValue = source[index];
    if (
      matchedTargetIndexes.has(index) ||
      matchedSourceIndexes.has(index) ||
      !isPlainObject(targetValue) ||
      !isPlainObject(sourceValue)
    ) {
      continue;
    }
    preserveMessageUnknownFields(desc, targetValue, sourceValue);
  }
}

function preserveFieldUnknownFields(field: DescField, target: unknown, source: unknown): void {
  switch (field.fieldKind) {
    case "message":
      if (isPlainObject(target) && isPlainObject(source)) {
        preserveMessageUnknownFields(field.message, target, source);
      }
      return;
    case "list":
      if (field.listKind === "message" && Array.isArray(target) && Array.isArray(source)) {
        preserveRepeatedMessageUnknownFields(field.message, target, source);
      }
      return;
    case "map":
      if (field.mapKind === "message" && isPlainObject(target) && isPlainObject(source)) {
        for (const [key, targetValue] of Object.entries(target)) {
          const sourceValue = source[key];
          if (isPlainObject(targetValue) && isPlainObject(sourceValue)) {
            preserveMessageUnknownFields(field.message, targetValue, sourceValue);
          }
        }
      }
      return;
    case "enum":
    case "scalar":
      return;
    default:
      throw new TypeError(`Unsupported field: ${String(field satisfies never)}`);
  }
}

function preserveMessageUnknownFields(desc: DescMessage, target: AnyObject, source: AnyObject): void {
  if (source["$unknown"]) {
    target["$unknown"] = structuredClone(source["$unknown"]);
  }

  for (const member of desc.members) {
    if (member.kind === "oneof") {
      const targetOneof = target[member.localName];
      const sourceOneof = source[member.localName];
      if (!(isPlainObject(targetOneof) && isPlainObject(sourceOneof))) {
        continue;
      }
      const targetCase = targetOneof["case"];
      if (typeof targetCase !== "string" || targetCase !== sourceOneof["case"]) {
        continue;
      }
      const activeField = member.fields.find((field) => field.localName === targetCase);
      if (activeField) {
        preserveFieldUnknownFields(activeField, targetOneof["value"], sourceOneof["value"]);
      }
      continue;
    }

    preserveFieldUnknownFields(member, target[member.localName], source[member.localName]);
  }
}

/**
 * Returns a validated protobuf message with unknown wire fields restored from
 * the corresponding surviving nodes in its edit source. The target is cloned
 * when a source is present.
 */
export function preserveProtoMessageSource<Desc extends DescMessage>(
  desc: Desc,
  target: MessageShape<Desc>,
  source?: MessageShape<Desc>
): MessageShape<Desc> {
  if (!source) {
    return target;
  }
  const message = clone(desc, target);
  preserveMessageUnknownFields(desc, message, source);
  return message;
}

/**
 * Builds an edited message from form values while retaining unknown wire
 * fields from the parsed source message. Unknown fields are not part of the
 * form model, so reconstructing a message from values alone would drop them.
 */
export function formValuesToProto<Desc extends DescMessage>(
  desc: Desc,
  values: Record<string, unknown>,
  source?: MessageShape<Desc>,
  options: ProtoConversionOptions = {}
): MessageShape<Desc> {
  const message = create(desc, formValuesToProtoInit(desc, values, options));
  if (source) {
    preserveMessageUnknownFields(desc, message, source);
  }
  return message;
}

export function protoFormValuesToPayload<Desc extends DescMessage>(
  desc: Desc,
  values: Record<string, unknown>,
  options: ProtoConversionOptions = {}
): unknown {
  try {
    const init = formValuesToProtoInit(desc, values, options);
    const message = create(desc, init);
    // `alwaysEmitImplicit: true` forces every scalar / message field to
    // appear in the serialized JSON even when the form hasn't been
    // touched. Without it, an untouched form renders as `{}` in the
    // summary panel — so users have to start typing just to see the
    // request shape. Emitting defaults gives them the full schema
    // skeleton up front and reduces the interactions needed to
    // visualise what will actually be sent.
    return toJson(desc, message, { alwaysEmitImplicit: true }) as unknown;
  } catch {
    try {
      return formValuesToProtoInit(desc, values, options);
    } catch {
      return values;
    }
  }
}

export function protoPayloadToFormValues<Desc extends DescMessage>(
  desc: Desc,
  payload: unknown
): FormValues | undefined {
  try {
    const message = fromJson(desc, (payload ?? {}) as JsonValue);
    return protoToFormValues(desc, message);
  } catch {
    return;
  }
}

function normalizeIssuePath(
  desc: DescMessage,
  issue: SchemaIssue,
  values: Record<string, unknown>
): (string | number)[] {
  if (!issue.path || issue.path.length === 0) {
    return [];
  }

  const normalizedPath: (string | number)[] = [];
  let currentDesc: DescMessage | undefined = desc;

  for (let index = 0; index < issue.path.length; index += 1) {
    const segment: StandardSchemaV1.PathSegment | PropertyKey | undefined = issue.path[index];
    const key = typeof segment === "object" && segment && "key" in segment ? segment.key : segment;

    if (typeof key === "number") {
      normalizedPath.push(key);
      continue;
    }

    if (!currentDesc || typeof key !== "string") {
      normalizedPath.push(String(key));
      continue;
    }

    const matchedField: DescField | undefined = currentDesc.field[key];
    const oneof = currentDesc.oneofs.find((candidate) => candidate.localName === key);

    if (oneof) {
      normalizedPath.push(oneof.localName);
      currentDesc = undefined;
      continue;
    }

    if (!matchedField) {
      normalizedPath.push(key);
      currentDesc = undefined;
      continue;
    }

    normalizedPath.push(matchedField.localName);

    if (matchedField.fieldKind === "map") {
      const nextSegment = issue.path[index + 1];
      const mapKey =
        typeof nextSegment === "object" && nextSegment && "key" in nextSegment ? nextSegment.key : nextSegment;
      const mapEntries = Array.isArray(values[matchedField.localName])
        ? (values[matchedField.localName] as ProtoMapFormEntry[])
        : [];
      const mapIndex = typeof mapKey === "string" ? mapEntries.findIndex((entry) => entry.key === mapKey) : -1;

      if (mapIndex !== -1 && issue.path.length > index + 2 && matchedField.mapKind === "message") {
        normalizedPath.push(mapIndex, "value");
        currentDesc = matchedField.message;
        index += 1;
        continue;
      }

      // If the protovalidate key no longer matches a rendered map entry, keep the error on the
      // map field itself instead of targeting a stale array index in RHF state.
      return normalizedPath;
    }

    if (matchedField.fieldKind === "message") {
      if (isWrapperDesc(matchedField.message) || PROTO_JSON_FALLBACK_TYPES.includes(matchedField.message.typeName)) {
        return normalizedPath;
      }
      currentDesc = matchedField.message;
      continue;
    }

    if (matchedField.fieldKind === "list" && matchedField.listKind === "message") {
      if (isWrapperDesc(matchedField.message) || PROTO_JSON_FALLBACK_TYPES.includes(matchedField.message.typeName)) {
        return normalizedPath;
      }
      // Guard against stale array indices: if the next segment is a numeric index,
      // verify the array still has that many entries. If not, anchor the error on
      // the list field itself (same fallback strategy as map fields).
      const nextSegment = issue.path[index + 1];
      const nextKey =
        typeof nextSegment === "object" && nextSegment && "key" in nextSegment ? nextSegment.key : nextSegment;
      if (typeof nextKey === "number") {
        const listEntries = values[matchedField.localName];
        if (!Array.isArray(listEntries) || nextKey >= listEntries.length) {
          return normalizedPath;
        }
      }
      currentDesc = matchedField.message;
      continue;
    }

    currentDesc = undefined;
  }

  return normalizedPath;
}

/** A Standard Schema issue whose path is already normalized to form paths. */
export interface NormalizedProtoIssue {
  message: string;
  path: (string | number)[];
}

export type NormalizedProtoValidationResult<Output> =
  | StandardSchemaV1.SuccessResult<Output>
  | { readonly issues: readonly NormalizedProtoIssue[] };

export interface ProtoValidationContext {
  /**
   * Restrict pathful issues to fields overlapping this mask. Message-level
   * issues remain visible because they cannot be attributed safely.
   */
  validationMask?: FieldMask | undefined;
}

const SIGNED_32_SCALARS = [ScalarType.INT32, ScalarType.SINT32, ScalarType.SFIXED32];
const UNSIGNED_32_SCALARS = [ScalarType.UINT32, ScalarType.FIXED32];
const SIGNED_64_SCALARS = [ScalarType.INT64, ScalarType.SINT64, ScalarType.SFIXED64];
const UNSIGNED_64_SCALARS = [ScalarType.UINT64, ScalarType.FIXED64];
const SIGNED_32_MIN = -2_147_483_648;
const SIGNED_32_MAX = 2_147_483_647;
const UNSIGNED_32_MAX = 4_294_967_295;
const SIGNED_64_MIN = -9_223_372_036_854_775_808n;
const SIGNED_64_MAX = 9_223_372_036_854_775_807n;
const UNSIGNED_64_MAX = 18_446_744_073_709_551_615n;

function getScalarConversionIssue(field: ScalarField, value: unknown): string | undefined {
  if (value === undefined || value === null || value === "") {
    return;
  }
  if (SIGNED_32_SCALARS.includes(field.scalar)) {
    const numericValue = normalizeNumberValue(value);
    if (
      numericValue === undefined ||
      !Number.isInteger(numericValue) ||
      numericValue < SIGNED_32_MIN ||
      numericValue > SIGNED_32_MAX
    ) {
      return "Enter a signed 32-bit integer.";
    }
  }
  if (UNSIGNED_32_SCALARS.includes(field.scalar)) {
    const numericValue = normalizeNumberValue(value);
    if (
      numericValue === undefined ||
      !Number.isInteger(numericValue) ||
      numericValue < 0 ||
      numericValue > UNSIGNED_32_MAX
    ) {
      return "Enter an unsigned 32-bit integer.";
    }
  }
  if (SIGNED_64_SCALARS.includes(field.scalar)) {
    const bigintValue = normalizeBigIntValue(value);
    if (bigintValue === undefined || bigintValue < SIGNED_64_MIN || bigintValue > SIGNED_64_MAX) {
      return "Enter a signed 64-bit integer.";
    }
  }
  if (UNSIGNED_64_SCALARS.includes(field.scalar)) {
    const bigintValue = normalizeBigIntValue(value);
    if (bigintValue === undefined || bigintValue < 0n || bigintValue > UNSIGNED_64_MAX) {
      return "Enter an unsigned 64-bit integer.";
    }
  }
  return;
}

function getMessageConversionIssue(field: MessageField, value: unknown): string | undefined {
  if (value === undefined || value === null || value === "") {
    return;
  }
  if (field.message.typeName === TIMESTAMP_TYPE) {
    return typeof value === "string" && !Number.isNaN(new Date(value).getTime())
      ? undefined
      : "Enter a valid date and time.";
  }
  if (field.message.typeName === DURATION_TYPE) {
    if (typeof value !== "string") {
      return "Enter a valid duration.";
    }
    try {
      fromJsonString(DurationSchema, JSON.stringify(value));
      return;
    } catch {
      return "Enter a valid duration.";
    }
  }
  if (field.message.typeName !== ANY_TYPE || !isPlainObject(value)) {
    return;
  }
  const { valueBase64 } = value as ProtoAnyFormValue;
  if (valueBase64 === undefined || valueBase64 === "") {
    return;
  }
  try {
    base64Decode(valueBase64);
    return;
  } catch {
    return "Enter valid base64 data.";
  }
}

function getMapConversionIssue(value: unknown): string | undefined {
  if (!Array.isArray(value)) {
    return;
  }
  const keys = value.flatMap((entry) => {
    if (!isPlainObject(entry)) {
      return [];
    }
    const key = entry["key"];
    return key === undefined || key === null || key === "" ? [] : [String(key)];
  });
  return new Set(keys).size === keys.length ? undefined : "Map keys must be unique.";
}

function getFormConversionIssues(desc: DescMessage, values: Record<string, unknown>): NormalizedProtoIssue[] {
  return desc.members.flatMap((member) => {
    if (member.kind === "oneof") {
      return [];
    }
    let message: string | undefined;
    if (member.fieldKind === "scalar") {
      message = getScalarConversionIssue(member, values[member.localName]);
    } else if (member.fieldKind === "message") {
      message = getMessageConversionIssue(member, values[member.localName]);
    } else if (member.fieldKind === "map") {
      message = getMapConversionIssue(values[member.localName]);
    }
    return message ? [{ message, path: [member.localName] }] : [];
  });
}

function toFailureResult(error: unknown): {
  readonly issues: readonly NormalizedProtoIssue[];
} {
  return {
    issues: [
      {
        message: error instanceof Error ? error.message : "Failed to validate protobuf form values.",
        path: [],
      },
    ],
  };
}

function normalizeValidationResult<Desc extends DescMessage>(
  desc: Desc,
  values: Record<string, unknown>,
  validationResult: StandardSchemaV1.Result<MessageValidType<Desc>>,
  fallbackValue: MessageShape<Desc>,
  context: ProtoValidationContext
): NormalizedProtoValidationResult<MessageValidType<Desc>> {
  if (validationResult.issues) {
    const issues = filterValidationIssues(
      desc,
      validationResult.issues.map((issue) => ({
        message: issue.message,
        path: normalizeIssuePath(desc, issue, values),
      })),
      context.validationMask
    );
    if (issues.length === 0) {
      return { value: fallbackValue as MessageValidType<Desc> };
    }
    return {
      issues,
    };
  }

  return validationResult;
}

function filterValidationIssues(
  desc: DescMessage,
  issues: readonly NormalizedProtoIssue[],
  validationMask?: FieldMask
): readonly NormalizedProtoIssue[] {
  if (!validationMask || validationMask.paths.includes("*")) {
    return issues;
  }

  const formPaths = validationMask.paths.flatMap((path) => {
    const formPath = protoPathToFormPath(desc, path);
    return formPath ? [formPath] : [];
  });

  return issues.filter((issue) => {
    if (issue.path.length === 0) {
      return true;
    }
    const issuePath = issue.path.join(".");
    return formPaths.some(
      (formPath) =>
        issuePath === formPath || issuePath.startsWith(`${formPath}.`) || formPath.startsWith(`${issuePath}.`)
    );
  });
}

/**
 * Shared validation pipeline: form values → proto init → `create()` →
 * protovalidate Standard Schema → issues re-pathed to FORM paths
 * (camelCase keys, oneofs flattened, map keys resolved to entry indices).
 *
 * Both `createProtoFormSchema` and `ProtoProvider.validateSchema` (and the
 * registry's react-hook-form resolver) flow through this single function.
 */
export function validateFormValuesAgainstProtoSchema<Desc extends DescMessage>(
  desc: Desc,
  values: Record<string, unknown>,
  schema: StandardSchemaV1<MessageShape<Desc>, MessageValidType<Desc>>,
  options: ProtoConversionOptions = {},
  source?: MessageShape<Desc>,
  context: ProtoValidationContext = {}
):
  | NormalizedProtoValidationResult<MessageValidType<Desc>>
  | Promise<NormalizedProtoValidationResult<MessageValidType<Desc>>> {
  try {
    const conversionIssues = filterValidationIssues(
      desc,
      getFormConversionIssues(desc, values),
      context.validationMask
    );
    if (conversionIssues.length > 0) {
      return { issues: conversionIssues };
    }
    const message = formValuesToProto(desc, values, source, options);
    const validationResult = schema["~standard"].validate(message);

    if (validationResult instanceof Promise) {
      return validationResult
        .then((result) => normalizeValidationResult(desc, values, result, message, context))
        .catch((error: unknown) => toFailureResult(error));
    }

    return normalizeValidationResult(desc, values, validationResult, message, context);
  } catch (error) {
    return toFailureResult(error);
  }
}

// Converts raw protovalidate error messages into human-readable messages.
// Acts as a safety net for standard buf.validate constraints that cannot carry
// custom messages. Proto-level CEL expressions with custom messages take
// priority. This utility only fires for generic fallback messages.

import { formatProtoformMessage, type ProtoformMessageFormatter } from "../core/messages.js";

const REGEX_ERROR_PATTERN = /regex pattern\s*`([^`]+)`/u;
const MIN_LEN_PATTERN = /^value length must be at least (\d+)/u;
const MAX_LEN_PATTERN = /^value length must be at most (\d+)/u;
const MIN_ITEMS_PATTERN = /^(?:value )?must contain at least (\d+)(?: item(?:\(s\)|s)?)?/u;
const MAX_ITEMS_PATTERN = /^(?:value )?must contain at most (\d+)(?: item(?:\(s\)|s)?)?/u;
const GTE_PATTERN = /^value must be greater than or equal to ([\d.]+)/u;
const LTE_PATTERN = /^value must be less than or equal to ([\d.]+)/u;
const GT_PATTERN = /^value must be greater than ([\d.]+)/u;
const LT_PATTERN = /^value must be less than ([\d.]+)/u;

interface PatternDescription {
  description: string;
  example: string;
}

const KNOWN_PATTERNS: Record<string, PatternDescription> = {
  "^[A-Z][A-Z0-9_]*$": {
    description: "Must be UPPER_SNAKE_CASE (start with a letter, then uppercase letters, digits, and underscores)",
    example: "AWS_ACCESS_KEY_ID",
  },
  "^[a-z][a-z0-9-]*$": {
    description: "Must be lowercase letters, digits, and hyphens (start with a letter)",
    example: "my-resource-name",
  },
  "^[a-z0-9][a-z0-9-]*$": {
    description: "Must be lowercase letters, digits, and hyphens (start with a letter or digit)",
    example: "my-resource-1",
  },
  "^$|^[A-Z][A-Z0-9_]*$": {
    description: "Must be empty or UPPER_SNAKE_CASE (uppercase letters, digits, and underscores)",
    example: "MY_API_KEY",
  },
  // Match the URL pattern with or without a trailing `$` anchor. Both
  // appear in protovalidate output depending on how the rule was authored.
  "^https?://.+": {
    description: "Must be a valid URL starting with http:// or https://",
    example: "https://example.com",
  },
  "^https?://.+$": {
    description: "Must be a valid URL starting with http:// or https://",
    example: "https://example.com",
  },
};

/** Known generic protovalidate messages that should be replaced by custom CEL messages when available. */
const GENERIC_MESSAGES = new Set(["value is required", "exactly one field is required in oneof"]);

/**
 * Returns true if the message is a generic protovalidate constraint message
 * (i.e., not a custom CEL message). Used by the resolver to prefer custom
 * messages over generic ones when a field has multiple validation errors.
 */
export function isGenericValidationMessage(message: string): boolean {
  if (GENERIC_MESSAGES.has(message)) {
    return true;
  }
  if (MIN_LEN_PATTERN.test(message) || MAX_LEN_PATTERN.test(message)) {
    return true;
  }
  if (REGEX_ERROR_PATTERN.test(message)) {
    return true;
  }
  if (
    MIN_ITEMS_PATTERN.test(message) ||
    MAX_ITEMS_PATTERN.test(message) ||
    GTE_PATTERN.test(message) ||
    LTE_PATTERN.test(message) ||
    GT_PATTERN.test(message) ||
    LT_PATTERN.test(message)
  ) {
    return true;
  }
  return false;
}

function humanizeLengthConstraint(message: string, formatter?: ProtoformMessageFormatter): string | undefined {
  const minLenMatch = MIN_LEN_PATTERN.exec(message);
  if (minLenMatch?.[1]) {
    const limit = Number(minLenMatch[1]);
    return limit === 1
      ? formatProtoformMessage(formatter, "validation.required", {}, "This field is required.")
      : formatProtoformMessage(formatter, "validation.min_length", { limit }, `Must be at least ${limit} characters.`);
  }
  const maxLenMatch = MAX_LEN_PATTERN.exec(message);
  if (maxLenMatch?.[1]) {
    const limit = Number(maxLenMatch[1]);
    return formatProtoformMessage(
      formatter,
      "validation.max_length",
      { limit },
      `Must be at most ${limit} characters.`
    );
  }
  return;
}

function humanizeItemConstraint(message: string, formatter?: ProtoformMessageFormatter): string | undefined {
  const minItemsMatch = MIN_ITEMS_PATTERN.exec(message);
  if (minItemsMatch?.[1]) {
    const limit = Number(minItemsMatch[1]);
    return formatProtoformMessage(
      formatter,
      "validation.min_items",
      { limit },
      limit === 1 ? "Add at least one item." : `Add at least ${limit} items.`
    );
  }
  const maxItemsMatch = MAX_ITEMS_PATTERN.exec(message);
  if (maxItemsMatch?.[1]) {
    const limit = Number(maxItemsMatch[1]);
    return formatProtoformMessage(
      formatter,
      "validation.max_items",
      { limit },
      limit === 1 ? "At most one item is allowed." : `At most ${limit} items are allowed.`
    );
  }
  return;
}

function humanizeNumericBound(message: string, formatter?: ProtoformMessageFormatter): string | undefined {
  const gteMatch = GTE_PATTERN.exec(message);
  if (gteMatch?.[1]) {
    return formatProtoformMessage(
      formatter,
      "validation.greater_than_or_equal",
      { limit: gteMatch[1] },
      `Must be ${gteMatch[1]} or greater.`
    );
  }
  const lteMatch = LTE_PATTERN.exec(message);
  if (lteMatch?.[1]) {
    return formatProtoformMessage(
      formatter,
      "validation.less_than_or_equal",
      { limit: lteMatch[1] },
      `Must be ${lteMatch[1]} or less.`
    );
  }
  const gtMatch = GT_PATTERN.exec(message);
  if (gtMatch?.[1]) {
    return formatProtoformMessage(
      formatter,
      "validation.greater_than",
      { limit: gtMatch[1] },
      `Must be greater than ${gtMatch[1]}.`
    );
  }
  const ltMatch = LT_PATTERN.exec(message);
  if (ltMatch?.[1]) {
    return formatProtoformMessage(
      formatter,
      "validation.less_than",
      { limit: ltMatch[1] },
      `Must be less than ${ltMatch[1]}.`
    );
  }
  return;
}

function humanizeRegexError(message: string, formatter?: ProtoformMessageFormatter): string | undefined {
  const regexMatch = REGEX_ERROR_PATTERN.exec(message);
  if (!regexMatch?.[1]) {
    return;
  }
  const known = KNOWN_PATTERNS[regexMatch[1]];
  const fallback = known ? `${known.description}. Example: ${known.example}` : message;
  return formatProtoformMessage(
    formatter,
    "validation.pattern",
    { example: known?.example ?? "", pattern: regexMatch[1] },
    fallback
  );
}

/**
 * Replace raw protovalidate error messages with human-readable descriptions.
 * Returns the original message if it's already a custom CEL message.
 */
export function humanizeValidationError(message: string, formatter?: ProtoformMessageFormatter): string {
  if (message === "value is required") {
    return formatProtoformMessage(formatter, "validation.required", {}, "Enter a value.");
  }
  if (message === "exactly one field is required in oneof") {
    return formatProtoformMessage(formatter, "validation.oneof_required", {}, "Select an option.");
  }

  return (
    humanizeLengthConstraint(message, formatter) ??
    humanizeItemConstraint(message, formatter) ??
    humanizeNumericBound(message, formatter) ??
    humanizeRegexError(message, formatter) ??
    message
  );
}

export const SERVER_FIELD_ERROR_FALLBACK = "Review this value and try again.";

/** Humanize a server field violation and ensure blank descriptions stay actionable. */
export function humanizeServerFieldError(description: string, formatter?: ProtoformMessageFormatter): string {
  const message = description.trim();
  return message
    ? humanizeValidationError(message, formatter)
    : formatProtoformMessage(formatter, "validation.server_field", {}, SERVER_FIELD_ERROR_FALLBACK);
}

import type { DescField, DescMessage, DescOneof } from "@bufbuild/protobuf";

/**
 * Convert a server-side proto field path into the camelCase form path used by
 * Protoform adapters. Oneof branches flatten under `{oneofLocalName}.value`.
 */
export function protoPathToFormPath(schema: DescMessage, serverPath: string): string | null {
  if (!serverPath) {
    return null;
  }
  const path = walk(schema, serverPath.split("."));
  return path ? path.join(".") : null;
}

function walk(current: DescMessage, segments: readonly string[]): string[] | null {
  if (segments.length === 0) {
    return [];
  }
  const [head, ...rest] = segments;
  if (!head) {
    return null;
  }
  const resolved = findMember(current, head);
  if (!resolved) {
    return null;
  }

  if (resolved.kind === "oneof") {
    if (rest.length === 0) {
      return [resolved.oneof.localName];
    }
    const [branchName, ...afterBranch] = rest;
    if (!branchName) {
      return null;
    }
    const branch = resolved.oneof.fields.find((candidate) => candidate.name === branchName);
    if (!branch) {
      return null;
    }
    const tail = walkInto(branch, afterBranch);
    return tail === null ? null : [resolved.oneof.localName, "value", ...tail];
  }

  const { field } = resolved;
  const formPath = field.oneof ? [field.oneof.localName, "value"] : [field.localName];
  if (rest.length === 0) {
    return formPath;
  }
  if (!field.message) {
    return null;
  }
  const tail = walk(field.message, rest);
  return tail === null ? null : [...formPath, ...tail];
}

function walkInto(field: DescField, segments: readonly string[]): string[] | null {
  if (segments.length === 0) {
    return [];
  }
  return field.message ? walk(field.message, segments) : null;
}

type Resolved = { kind: "field"; field: DescField } | { kind: "oneof"; oneof: DescOneof };

function findMember(message: DescMessage, protoName: string): Resolved | undefined {
  for (const member of message.members) {
    if (member.kind === "oneof") {
      if (member.name === protoName) {
        return { kind: "oneof", oneof: member };
      }
      const field = member.fields.find((candidate) => candidate.name === protoName);
      if (field) {
        return { field, kind: "field" };
      }
    } else if (member.name === protoName) {
      return { field: member, kind: "field" };
    }
  }
  return;
}

import {
  createRegistry,
  type DescMessage,
  isMessage,
  type MessageShape,
  type MessageValidType,
} from "@bufbuild/protobuf";
import { usedTypes } from "@bufbuild/protobuf/reflect";
import { createValidator, RuntimeError, type ValidatorOptions, type Violation } from "@bufbuild/protovalidate";
import type { StandardSchemaV1 } from "../core/index.js";
import type { ProtoformMessageFormatter } from "../core/messages.js";
import { humanizeValidationError } from "./humanize-validation-error.js";

function violationToIssue(violation: Violation, formatter?: ProtoformMessageFormatter): StandardSchemaV1.Issue {
  const path: PropertyKey[] = [];

  for (const segment of violation.field) {
    switch (segment.kind) {
      case "field":
        if (segment.oneof) {
          path.push(segment.oneof.localName, "value");
        } else {
          path.push(segment.localName);
        }
        break;
      case "oneof":
        path.push(segment.localName);
        break;
      case "list_sub":
        path.push(segment.index);
        break;
      case "map_sub":
        path.push(
          typeof segment.key === "string" || typeof segment.key === "number" ? segment.key : String(segment.key)
        );
        break;
      case "extension":
        path.push(`[${segment.typeName}]`);
        break;
      default:
        throw new TypeError(`Unsupported violation path segment: ${String(segment satisfies never)}`);
    }
  }

  const message = humanizeValidationError(violation.message, formatter);
  return path.length > 0 ? { message, path } : { message };
}

export function createDescriptorAwareStandardSchema<Desc extends DescMessage>(
  desc: Desc,
  options?: ValidatorOptions & { formatMessage?: ProtoformMessageFormatter | undefined }
): StandardSchemaV1<MessageShape<Desc>, MessageValidType<Desc>> {
  const { formatMessage, ...validatorOptions } = options ?? {};
  const registry = createRegistry(
    desc,
    ...usedTypes(desc),
    ...(validatorOptions.registry ? [validatorOptions.registry] : [])
  );
  const validator = createValidator({ ...validatorOptions, registry });

  return {
    "~standard": {
      validate: (value) => {
        if (typeof value !== "object" || value === null) {
          return { issues: [{ message: "Expected an object" }] };
        }
        if (!isMessage(value, desc)) {
          return { issues: [{ message: "Expected a protobuf message" }] };
        }

        const result = validator.validate(desc, value);
        switch (result.kind) {
          case "valid":
            return { value: result.message };
          case "invalid":
            return { issues: result.violations.map((violation) => violationToIssue(violation, formatMessage)) };
          case "error":
            if (result.error instanceof RuntimeError) {
              // Runtime failures are schema defects, not user input errors. Fail
              // open so form adapters never surface CEL internals to end users.
              return {
                value: result.message as MessageValidType<Desc>,
              };
            }
            return { issues: [{ message: result.error.message }] };
          default:
            return result satisfies never;
        }
      },
      vendor: "protoform",
      version: 1,
    },
  };
}
